    private static int stanceSpellKiCost(String stance,String spell,int level){String st=n(stance),sp=n(spell);String[][] rows;if(st.equals("galo"))rows=new String[][]{{"3","2","Lufada de Vento|Muralha de Vento"},{"6","3","Voo|Forma Gasosa"},{"11","5","Caminhar no Vento"},{"17","7","Controlar o Clima|Vendaval"}};else if(st.equals("rato"))rows=new String[][]{{"3","2","Criar ou Destruir Água|Armadura de Agathys|Controlar a Água"},{"6","3","Nublar|Maremoto|Respirar na Água"},{"11","5","Cone de Frio|Manto de Gelo"},{"17","7","Tsunami"}};else if(st.equals("tigre"))rows=new String[][]{{"3","2","Raio Guiador"},{"6","3","Passo Trovejante|Relâmpago|Aura de Pureza"},{"11","5","Corrente de Relâmpagos|Parede de Luz"},{"17","7","Coroa de Estrelas"}};else if(st.equals("dragao"))rows=new String[][]{{"3","2","Mãos Flamejantes|Chama Contínua|Esquentar Metal"},{"6","3","Coluna de Chamas|Bola de Fogo"},{"11","5","Muralha de Fogo|Manto de Chamas"},{"17","7","Tempestade de Fogo"}};else if(st.equals("serpente"))rows=new String[][]{{"3","2","Silêncio|Infligir Ferimentos"},{"6","3","Imobilizar Monstro"},{"11","5","Desintegrar"},{"17","7","Enfraquecer Intelecto"}};else if(st.equals("macaco"))rows=new String[][]{{"3","2","Erupção de Terra|Agarrão da Terra"},{"6","3","Tremor de Terra|Mesclar|Moldar Rochas|Pele de Pedra"},{"11","5","Manto de Pedra|Mover Terra|Ossos da Terra"},{"17","7","Terremoto"}};else return -1;for(String[] r:rows){if(level<Integer.parseInt(r[0]))continue;for(String x:r[2].split("\\|"))if(n(x).equals(sp))return Integer.parseInt(r[1]);}return -1;}
