    private static void res(JSONObject r,String key,int max,String recharge)throws Exception{JSONObject x=r.optJSONObject(key);if(x==null)x=new JSONObject();x.put("max",max);if(!x.has("current"))x.put("current",max);else x.put("current",Math.max(0,Math.min(max,x.optInt("current",max))));x.put("recharge",recharge);r.put(key,x);}
    private static boolean spendSpecies(JSONObject s,String key,int amount)throws Exception{JSONObject r=speciesResources(s),x=r.optJSONObject(key);if(x==null||x.optInt("current",0)<amount)return false;x.put("current",x.optInt("current")-amount);r.put(key,x);s.put("species_resources",r);return true;}
    private static void restoreSpecies(JSONObject s,String key){try{JSONObject r=speciesResources(s),x=r.optJSONObject(key);if(x!=null){x.put("current",x.optInt("max",0));r.put(key,x);s.put("species_resources",r);}}catch(Exception ignored){}}
