    private static void restoreRecharge(JSONObject s,String recharge){try{for(String bucket:new String[]{"species_resources","subclass_resources"}){JSONObject r=s.optJSONObject(bucket);if(r==null)continue;Iterator<String>it=r.keys();while(it.hasNext()){String k=it.next();JSONObject x=r.optJSONObject(k);if(x!=null&&recharge.equals(x.optString("recharge")))x.put("current",x.optInt("max",0));}}}catch(Exception ignored){}}
